27	//Bellman-Ford relaxation. A vertex d joins the next frontier iff this round
28	//lowered its tentative distance; Visited[] makes sure d is added at most once
29	//per round even when several in-edges improve it.
30	struct BF_F {
31	  intE* ShortestPathLen;
32	  int* Visited;
33	  BF_F(intE* _ShortestPathLen, int* _Visited) :
34	    ShortestPathLen(_ShortestPathLen), Visited(_Visited) {}
35	  inline bool update (uintE s, uintE d, intE edgeLen) { //Update ShortestPathLen if found a better path
36	    intE newDist = ShortestPathLen[s] + edgeLen;
37	    if(ShortestPathLen[d] > newDist) {
38	      ShortestPathLen[d] = newDist;
39	      if(Visited[d] == 0) { Visited[d] = 1; return 1; } //first improvement this round
40	    }
41	    return 0;
42	  }
43	  inline bool updateAtomic (uintE s, uintE d, intE edgeLen){ //atomic version of Update
44	    intE newDist = ShortestPathLen[s] + edgeLen;
45	    return (writeMin(&ShortestPathLen[d],newDist) &&
46		    CAS(&Visited[d],0,1));
47	  }
48	  //cond function is always true: any vertex may still be improved
49	  inline bool cond (uintE d) { return cond_true(d); }
50	};
51	
52	//vertex map function to reset Visited before the next round of relaxations
53	struct BF_Vertex_F {
54	  int* Visited;
55	  BF_Vertex_F(int* _Visited) : Visited(_Visited) {}
56	  inline bool operator() (uintE i){
57	    Visited[i] = 0;
58	    return 1;
59	  }
60	};
