63	void Compute(graph<vertex>& GA, commandLine P) {
64	  long start = P.getOptionLongValue("-r",0);
65	  long n = GA.n;
66	  //initialize ShortestPathLen to "infinity", except for the source
67	  intE* ShortestPathLen = newA(intE,n);
68	  {parallel_for(long i=0;i<n;i++) ShortestPathLen[i] = INT_E_MAX;}
69	  ShortestPathLen[start] = 0;
70	
71	  int* Visited = newA(int,n);
72	  {parallel_for(long i=0;i<n;i++) Visited[i] = 0;}
73	
74	  vertexSubset Frontier(n,start); //initial frontier contains only the source
75	
76	  long round = 0;
77	  bool negativeCycle = false;
78	  while(!Frontier.isEmpty()){
79	    if(round == n) {
80	      //a simple shortest path uses at most n-1 edges, so still making
81	      //progress after n rounds means some reachable cycle has negative weight
82	      negativeCycle = true;
83	      break;
84	    }
85	    //relax all out-edges of the frontier; dense_forward avoids the (useless)
86	    //dense in-edge scan since cond is always true
87	    vertexSubset output = edgeMap(GA, Frontier, BF_F(ShortestPathLen,Visited), GA.m/20, dense_forward);
88	    vertexMap(output,BF_Vertex_F(Visited)); //clear Visited for the next round
89	    Frontier.del();
90	    Frontier = output; //set new frontier
91	    round++;
92	  }
93	  Frontier.del();
94	
95	  if(negativeCycle) cout << "BellmanFord negative weight cycle" << endl;
96	
97	  //count the vertices reachable from the source and total up their distances
98	  long reachable = 0, sum = 0;
99	  for(long i=0;i<n;i++) {
100	    if(ShortestPathLen[i] != INT_E_MAX) { reachable++; sum += ShortestPathLen[i]; }
101	  }
102	  cout << "BellmanFord rounds: " << round << endl;
103	  cout << "BellmanFord reachable: " << reachable << endl;
104	  cout << "BellmanFord sum: " << sum << endl;
105	
106	  free(Visited); free(ShortestPathLen);
107	}
